#!/usr/bin/env node
// Turn the reviewable JSON sources into one classic script for static hosting.
// The application runs without a build service, but contributors must check in
// this generated file after editing catalogue data.

import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { repoRoot } from './load-data.mjs';

const readJson = (name) => JSON.parse(readFileSync(join(repoRoot, name), 'utf8'));
const books = readJson('data/books.json');
const characters = readJson('data/characters.json');
const identities = readJson('data/work-identities.json');
const publisherCollections = readJson('data/publisher-collections.json');
const readingRoutes = readJson('data/reading-routes.json');
const characterAppearances = readJson('data/character-appearances.json');
const events = readJson('data/events.json');
const publisherWorkFacts = readJson('data/publisher-work-facts.json');
const primarchFormatReview = readJson('data/primarch-format-review.json');
const collections = readJson('data/collections.json');
const legacyTransferKeys = readJson('data/transfer-code-legacy-228.json');

const output = [
    '// Generated by node tools/build-catalogue.mjs. Edit data/*.json, not this file.',
    `const characterData = ${JSON.stringify(characters)};`,
    `const bookData = ${JSON.stringify(books)};`,
    `const workIdentityData = ${JSON.stringify(identities)};`,
    `const publisherCollectionsData = ${JSON.stringify(publisherCollections)};`,
    `const readingRoutesData = ${JSON.stringify(readingRoutes)};`,
    `const characterAppearancesData = ${JSON.stringify(characterAppearances)};`,
    `const eventData = ${JSON.stringify(events)};`,
    `const publisherWorkFactsData = ${JSON.stringify(publisherWorkFacts)};`,
    `const primarchFormatReviewData = ${JSON.stringify(primarchFormatReview)};`,
    `const collectionIdentityData = ${JSON.stringify(collections)};`,
    `const legacyTransferKeysData = ${JSON.stringify(legacyTransferKeys)};`,
    '',
].join('\n');
const path = join(repoRoot, 'catalogue-data.js');

if (process.argv.includes('--check')) {
    if (readFileSync(path, 'utf8') !== output) {
        console.error('catalogue-data.js is stale. Run node tools/build-catalogue.mjs');
        process.exit(1);
    }
    console.log('Catalogue build is current.');
} else {
    writeFileSync(path, output);
    console.log(`Wrote catalogue-data.js with ${Object.keys(books).length} entries.`);
}
